edits.oldText:
derived = set()
for rule in rules:
    bindings: list[dict[str, str]] = [{}]
    for premise in rule.body:
        candidates: tuple[Atom, ...] = index.get(premise.pred, ())
        next_bindings: list[dict[str, str]] = []
        for binding in bindings:
            for candidate in candidates:
                if budget <= 0:
                    raise IndexedLimitError(
                        "indexed.max_fact_checks is exhausted "
                        "before the closure stabilises")
                budget -= 1
                match = _match(premise, candidate, binding)
                if match is not None:
                    next_bindings.append(match)
        bindings = next_bindings
    for binding in bindings:
        derived.add(_instantiate(rule.head, binding))
